 benefits", "children": [{"id": "a2f789cd-f431-423f-9322-6d8bf003402a", "type": "concept", "title": "American opportunity credit"}, {"id": "4f8cf557-c71b-4869-bea8-07e57800d3c0", "type": "concept", "title": "Lifetime learning credit"}, {"id": "6b41bd3b-b03b-4b5e-b3a9-1e7c852b1968", "type": "concept", "title": "529 plans"}, {"id": "200d1bad-3734-498c-a99d-33507a2811af", "type": "concept", "title": "Student loan interest"}], "description": "Education provisions support saving and paying for qualifying education costs."}, {"id": "7a967cc9-80c4-4990-8871-6a00189238f9", "type": "subtopic", "title": "Family tax issues", "children": [{"id": "0b016fd9-64e3-4469-bbbb-21286eb357e3", "type": "concept", "title": "Child-related credits"}, {"id": "8861e733-5962-44d6-a1eb-4172708453a4", "type": "concept", "title": "Kiddie tax overview"}, {"id": "7787db5a-e364-4087-abb9-d1be9359eba9", "type": "concept", "title": "Assignment of income"}, {"id": "1d0d3ba1-df97-4ee1-abaa-e16947412ac9", "type": "concept", "title": "Filing for dependents"}], "description": "Family taxation requires translating household facts into dependency, credits, and assignment rules."}]}, {"id": "05442507-7c45-4d72-92f7-bdc336eeef7a", "type": "topic", "title": "Individual Business, Gig, Rental, and Self-Employment Income", "description": "Connect individual taxation to Schedule C, rental activity, self-employment tax, and basic business deductions.", "children": [{"id": "3a1b45c8-99de-4ae5-b8e5-ec2b6c45f21b", "type": "subtopic", "title": "Schedule C activity", "children": [{"id": "2589164c-85ae-439a-aabb-46f507b248e6", "type": "concept", "title": "Gross receipts"}, {"id": "7556dbd0-c66e-4816-a20b-a226a33193e6", "type": "concept", "title": "Ordinary and necessary expenses"}, {"id": "0761afc7-f0d0-43ba-9c59-33ab41024955", "type": "concept", "title": "Home office overview"}, {"id": "2692f54a-53f7-4b00-84ae-4a8ff9dc563e", "type": "concept", "title": "Business vs hobby"}], "description": "Many individuals have business