", "title": "Character"}, {"id": "4da629aa-47f5-4840-9ddc-368a463f0859", "type": "concept", "title": "Entity and account choice"}, {"id": "5e52d0fa-7bdb-44d8-99b0-4539d309c2c1", "type": "concept", "title": "Multi-year view"}], "description": "Planning evaluates alternatives before transactions occur."}, {"id": "7bcf0275-836c-4e77-9ecf-fdb123fb6acc", "type": "subtopic", "title": "Penalties", "children": [{"id": "2ea92304-c7b5-4040-9e37-f8051bb87a3a", "type": "concept", "title": "Accuracy-related penalties"}, {"id": "1bf9413f-87ac-4ca9-bfbd-ea5937324938", "type": "concept", "title": "Failure to file"}, {"id": "ecc8baf6-93e3-4d3d-a365-9c6f11892f03", "type": "concept", "title": "Failure to pay"}, {"id": "535693f5-5c99-44b0-8f23-11760a54600f", "type": "concept", "title": "Preparer penalties"}], "description": "Penalty rules encourage accurate reporting and responsible positions."}, {"id": "aa39df6f-1886-44b9-808b-615ee27fba50", "type": "subtopic", "title": "Professional ethics", "children": [{"id": "e63b61ef-d55a-44b9-8d1b-f7237bb2c037", "type": "concept", "title": "Circular 230"}, {"id": "5d7518d9-0569-452f-b703-0a3e6c3db760", "type": "concept", "title": "Conflicts of interest"}, {"id": "cfea7c6a-49e4-47ff-8d31-872f4170d52e", "type": "concept", "title": "Due diligence"}, {"id": "d0aec520-93e5-4296-a6f7-9b30b865446b", "type": "concept", "title": "Communicating uncertainty"}], "description": "Ethics marks the boundary between legitimate planning and improper tax avoidance."}]}], "dbBacked": true}$fitijson$::jsonb,
