  data = $fitijson${"slug": "federal-income-tax-individuals", "title": "Federal Income Tax (Individuals)", "description": "Understand how federal individual income tax is created, administered, researched, and interpreted. This syllabus is for education and curriculum planning, not personal tax, legal, or financial advice.", "topics": [{"id": "c552e8e9-a996-4d9e-9329-0d3b1969de84", "type": "topic", "title": "U.S. Federal Tax System, Authority, and Research Hierarchy", "description": "Understand how federal individual income tax is created, administered, researched, and interpreted.", "children": [{"id": "f1f6025e-6803-475a-b858-6809b86a98f5", "type": "subtopic", "title": "Sources of tax law", "children": [{"id": "6e98e023-27d8-4f7b-96a1-412942649e56", "type": "concept", "title": "Internal Revenue Code"}, {"id": "b5db1204-432d-4b5b-ad23-45b5993909ba", "type": "concept", "title": "Treasury regulations"}, {"id": "d2e9b193-8af1-4cc6-80a9-4627fb99adff", "type": "concept", "title": "Revenue rulings and procedures"}, {"id": "60070066-70d3-428b-a57b-33abb726b41b", "type": "concept", "title": "Cases and administrative guidance"}], "description": "Tax work begins by knowing which authorities control and how much weight they carry."}, {"id": "9775a699-449c-4c87-961d-03ef89053f19", "type": "subtopic", "title": "Tax administration", "children": [{"id": "0c12ef13-31e3-479c-80f5-2610d5ea3824", "type": "concept", "title": "IRS role"}, {"id": "414cc7a2-9c79-44f5-a213-df9e5e79d778", "type": "concept", "title": "Treasury role"}, {"id": "2d044dc5-4709-4717-9342-4d6ecc4e79d4", "type": "concept", "title": "Tax Court role"}, {"id": "9f7950e5-ad2f-4974-9823-75434fe9f791", "type": "concept", "title": "Assessment and collection overview"}], "description": "Administration explains how the IRS interprets, processes, audits, and enforces the tax law."}, {"id": "a1ae3bb7-5e47-4cb3-9465-c5112d184172", "type": "subtopic", "title": "Research hierarchy", "children": [{"id": "0b5419b4-149d-428e-93c6-